import PDFDocument from "pdfkit";
import { SHEET, fitColumns, paginate } from "./layout.js";

// Every report - department or crop, any period - is laid out the same way:
//
//   Keiyian Farmers Cooperative Society Ltd
//   Nuru ya Jamii
//   Sales report - November 2026
//   Generated by <name> on 08 Nov 2026, 21:24 EAT
//
// then the Summary across the page, one ruled table per section, the
// sign-off lines at the foot of the last page and, on every page, "This is a
// system generated report." with the time and the page number. The PDF is
// A4 landscape, paged the same way as the report on screen (see layout.js).
//
// A report: { heading, summary: [{ label, value, type? }], sections: [{ title, columns, rows, totals?, totalLabel?, emptyText? }] }

export const ORGANISATION = "Keiyian Farmers Cooperative Society Ltd";
export const MOTTO = "Nuru ya Jamii";
export const SIGN_OFF = ["Prepared by", "Checked by", "Confirmed by"];
export const SYSTEM_NOTE = "This is a system generated report.";

const SHORT = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const NUMERIC = ["money", "number", "percent"];

const money = (value) => Number(value || 0).toLocaleString("en-KE", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const number = (value) => (value === "" || value == null ? "" : Number(value).toLocaleString("en-KE", { maximumFractionDigits: 2 }));
const percent = (value) => (value === "" || value == null ? "" : `${number(value)}%`);
/** "02 May 2024" */
const dateText = (value) => {
  if (!value) return "";
  const d = new Date(value);
  return `${String(d.getUTCDate()).padStart(2, "0")} ${SHORT[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
};
const isoText = (value) => (value ? new Date(value).toISOString().slice(0, 10) : "");

/** "08 Nov 2026, 21:24 EAT" - the cooperative works in Nairobi time. */
export const generatedStamp = (date = new Date()) =>
  `${date.toLocaleString("en-GB", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit", hour12: false, timeZone: "Africa/Nairobi" })} EAT`;

export const formatCell = (value, type) => {
  if (type === "percent") return percent(value);
  if (type === "money") return value === "" || value == null ? "" : money(value);
  if (type === "number") return number(value);
  if (type === "date" || value instanceof Date) return dateText(value);
  return value == null ? "" : String(value);
};

/** A summary figure as it reads in the Summary table. */
export const summaryText = (item) => {
  if (item.type === "money") return `KES ${money(item.value)}`;
  if (item.type === "percent") return percent(item.value);
  if (item.type === "text") return String(item.value ?? "");
  return number(item.value);
};

/** The report's key figures as a two-column table. */
export const summarySection = (report) => ({
  title: "Summary",
  columns: [{ key: "item", label: "Item" }, { key: "value", label: "Value", align: "right" }],
  rows: report.summary.map((item) => ({ item: item.label, value: summaryText(item) })),
  width: 0.5,
});

const options = (meta) => ({
  organisation: meta.organisation || ORGANISATION,
  motto: meta.motto ?? MOTTO,
  generatedBy: meta.generatedBy || "the system",
  generated: generatedStamp(meta.generatedAt ? new Date(meta.generatedAt) : new Date()),
  emptyText: meta.emptyText || "No records for this period.",
  signatures: meta.signatures || SIGN_OFF,
});

// ---------------------------------------------------------------------
// CSV (opens in Excel): each report's header, Summary, then its tables.
// ---------------------------------------------------------------------
const csvCell = (value) => {
  const text = value == null ? "" : String(value);
  return /[",\n\r]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
};
const csvRaw = (value, type) => {
  if (value instanceof Date || type === "date") return isoText(value);
  if (NUMERIC.includes(type)) return value === "" || value == null ? "" : Number(value);
  return value;
};

export const toCsv = (reports, meta) => {
  const { organisation, motto, generatedBy, generated } = options(meta);
  const lines = [];
  const row = (cells) => lines.push(cells.map(csvCell).join(","));
  reports.forEach((report, index) => {
    if (index > 0) lines.push("", "");
    row([organisation]);
    if (motto) row([motto]);
    row([report.heading]);
    row([`Generated by ${generatedBy} on ${generated}`]);
    lines.push("");
    row(["Summary"]);
    row(["Item", "Value"]);
    for (const item of report.summary) row([item.label, item.type === "text" ? item.value : csvRaw(item.value, item.type || "number")]);
    for (const section of report.sections) {
      lines.push("");
      row([section.title]);
      row(section.columns.map((c) => c.label));
      if (!section.rows.length) row([section.emptyText || "No records"]);
      for (const data of section.rows) row(section.columns.map((c) => csvRaw(data[c.key], c.type)));
      if (section.totals) row(section.columns.map((c, i) => (i === 0 ? section.totalLabel || "Total" : section.totals[c.key] ?? "")));
    }
  });
  lines.push("");
  row([SYSTEM_NOTE]);
  row(["Generated", generated, "by", generatedBy]);
  return `﻿${lines.join("\r\n")}\r\n`;
};

// ---------------------------------------------------------------------
// PDF: A4 landscape pages, laid out by layout.js exactly as the screen and
// the printout are. Centred header, then ruled tables sized to their
// content, the sign-off at the foot of the last page, and the footer with
// the page number on every page.
// ---------------------------------------------------------------------
const GREEN = "#40532a";
const INK = "#19271f";
const MUTED = "#5e6b5e";
const RED = "#9f1239";
const GRID = "#b7c4b2";
const HEAD_FILL = "#e6ede2";
const TOTAL_FILL = "#f1f5ef";
const REGULAR = "Helvetica";
const BOLD = "Helvetica-Bold";
const ITALIC = "Helvetica-Oblique";

const MM = 72 / 25.4;
const PAGE_WIDTH = SHEET.width * MM;
const PAGE_HEIGHT = SHEET.height * MM;
const MARGIN = SHEET.margin * MM;
const CONTENT_WIDTH = PAGE_WIDTH - 2 * MARGIN;
const BODY_BOTTOM = PAGE_HEIGHT - MARGIN - SHEET.footer * MM;
const BODY_HEIGHT = BODY_BOTTOM - MARGIN;
// Table type: smaller sizes only for tables too wide for the page at the first.
const TYPE_SIZES = [8.5, 7.75, 7];
const PAD_X = 4.5;
const PAD_Y = 3.5;
const TITLE_SIZE = 10.5;
const TABLE_GAP = 14;
const KEEP_ON_ONE_LINE = ["money", "number", "percent", "date"];

const looksNegative = (text) => /^(KES )?-\d/.test(text);
const alignsRight = (column) => column.align === "right" || NUMERIC.includes(column.type);
const words = (text) => String(text ?? "").split(/\s+/).filter(Boolean);

/** The Summary as a full-width table of two item/value pairs a row, read down the left pair then the right. */
export const summaryGrid = (report) => {
  const half = Math.ceil(report.summary.length / 2);
  return {
    title: "Summary",
    pairs: true,
    columns: [
      { key: "item", label: "Item" }, { key: "value", label: "Value", align: "right" },
      { key: "item2", label: "Item" }, { key: "value2", label: "Value", align: "right" },
    ],
    rows: Array.from({ length: half }, (_, i) => {
      const [left, right] = [report.summary[i], report.summary[i + half]];
      return { item: left.label, value: summaryText(left), item2: right?.label ?? "", value2: right ? summaryText(right) : "" };
    }),
  };
};

export const toPdf = (reports, meta) => new Promise((resolve, reject) => {
  const { organisation, motto, generatedBy, generated, emptyText, signatures } = options(meta);
  const doc = new PDFDocument({
    size: "A4",
    layout: "landscape",
    margin: 0,
    info: { Title: reports.map((r) => r.heading).join("; ") || "Report", Author: organisation },
  });
  const chunks = [];
  doc.on("data", (chunk) => chunks.push(chunk));
  doc.on("end", () => resolve(Buffer.concat(chunks)));
  doc.on("error", reject);

  const widthOf = (text, font, size) => doc.font(font).fontSize(size).widthOfString(String(text ?? ""));
  const heightOf = (text, font, size, width) => doc.font(font).fontSize(size).heightOfString(String(text || " "), { width });
  const lineOf = (font, size) => heightOf("Xg", font, size, 1000);

  // ---- Measuring: each table's column widths, type size and row heights.
  const cellsOf = (section) => section.rows.map((data) => section.columns.map((c) => (section.pairs ? data[c.key] : formatCell(data[c.key], c.type))));
  const totalsOf = (section) => section.totals && section.columns.map((c, i) => (i === 0 ? section.totalLabel || "Total" : section.totals[c.key] == null ? "" : formatCell(section.totals[c.key], c.type)));

  const widthsFor = (section, cells, totals, size) => {
    if (section.pairs) {
      // Two equal halves; in each, the value takes what its longest figure needs.
      const value = Math.max(widthOf("Value", BOLD, size), ...cells.flatMap((row) => [widthOf(row[1], REGULAR, size), widthOf(row[3], REGULAR, size)])) + 2 * PAD_X + 2;
      const half = CONTENT_WIDTH / 2;
      return [half - value, value, half - value, value];
    }
    const sizes = section.columns.map((column, i) => {
      const texts = cells.map((row) => row[i]);
      const bold = totals ? [totals[i]] : [];
      const longest = Math.max(0, ...texts.map((t) => widthOf(t, REGULAR, size)), ...bold.map((t) => widthOf(t, BOLD, size)));
      const oneLine = KEEP_ON_ONE_LINE.includes(column.type) || alignsRight(column);
      const longestWord = oneLine ? longest : Math.max(0, ...texts.flatMap(words).map((w) => widthOf(w, REGULAR, size)), ...bold.flatMap(words).map((w) => widthOf(w, BOLD, size)));
      const label = widthOf(column.label, BOLD, size);
      const labelWord = Math.max(0, ...words(column.label).map((w) => widthOf(w, BOLD, size)));
      const pad = 2 * PAD_X + 1.5;
      return { min: Math.max(labelWord, longestWord) + pad, max: Math.max(label, longest) + pad };
    });
    return fitColumns(sizes, CONTENT_WIDTH);
  };

  const measureTable = (section) => {
    const cells = cellsOf(section);
    const totals = totalsOf(section);
    let size = TYPE_SIZES[0];
    let widths = null;
    for (const candidate of TYPE_SIZES) {
      size = candidate;
      widths = widthsFor(section, cells, totals, size);
      if (widths) break;
    }
    if (!widths) {
      // Wider than the page even in the smallest type: share the page in proportion and let long words break.
      const sizes = section.columns.map((c) => widthOf(c.label, BOLD, size) + 2 * PAD_X);
      const all = sizes.reduce((a, b) => a + b, 0);
      widths = sizes.map((w) => (w / all) * CONTENT_WIDTH);
    }
    const rowHeight = (row, font) => Math.max(...row.map((text, i) => heightOf(text, font, size, widths[i] - 2 * PAD_X))) + 2 * PAD_Y;
    const header = section.columns.map((c) => c.label);
    const empty = section.emptyText || emptyText;
    return {
      section, cells, totals, size, widths, header, empty,
      head: rowHeight(header, BOLD),
      rows: cells.length ? cells.map((row) => rowHeight(row, REGULAR)) : [heightOf(empty, ITALIC, size, CONTENT_WIDTH - 2 * PAD_X) + 2 * PAD_Y],
      foot: totals ? rowHeight(totals, BOLD) : 0,
    };
  };

  const titleHeight = lineOf(BOLD, TITLE_SIZE) + 5;

  // ---- Drawing. Each drawing function returns the height it used, so
  // measuring and drawing cannot disagree.
  const drawHeader = (report, draw) => {
    let y = MARGIN;
    const line = (text, font, size, color, after = 0) => {
      const height = heightOf(text, font, size, CONTENT_WIDTH);
      if (draw) doc.fillColor(color).font(font).fontSize(size).text(text, MARGIN, y, { width: CONTENT_WIDTH, align: "center" });
      y += height + after;
    };
    line(organisation, BOLD, 15, GREEN);
    if (motto) line(motto, ITALIC, 9.5, MUTED);
    y += 5;
    line(report.heading, BOLD, 12.5, INK);
    line(`Generated by ${generatedBy} on ${generated}`, REGULAR, 9, MUTED);
    y += 6;
    if (draw) doc.moveTo(MARGIN, y).lineTo(MARGIN + CONTENT_WIDTH, y).strokeColor(GREEN).lineWidth(1.5).stroke();
    y += 14;
    return y - MARGIN;
  };

  const drawRunningHeader = (report, draw) => {
    const height = lineOf(BOLD, 8);
    if (draw) {
      doc.fillColor(GREEN).font(BOLD).fontSize(8).text(organisation, MARGIN, MARGIN, { width: CONTENT_WIDTH / 2, lineBreak: false });
      doc.fillColor(MUTED).font(REGULAR).fontSize(8).text(report.heading, MARGIN + CONTENT_WIDTH / 2, MARGIN, { width: CONTENT_WIDTH / 2, align: "right", lineBreak: false });
      doc.moveTo(MARGIN, MARGIN + height + 4).lineTo(MARGIN + CONTENT_WIDTH, MARGIN + height + 4).strokeColor(GRID).lineWidth(0.5).stroke();
    }
    return height + 14;
  };

  const SIGN_ROW = 26;
  const signOffHeight = 12 + signatures.length * SIGN_ROW;
  const drawSignOff = () => {
    // Three ruled lines across the page: name, signature and date.
    const label = Math.max(...signatures.map((role) => widthOf(`${role}:`, REGULAR, 9))) + 10;
    const nameEnd = MARGIN + CONTENT_WIDTH * 0.5;
    const signatureAt = nameEnd + 18;
    const signatureEnd = MARGIN + CONTENT_WIDTH * 0.77;
    const dateAt = signatureEnd + 18;
    const end = MARGIN + CONTENT_WIDTH;
    let y = BODY_BOTTOM - signOffHeight + 12;
    for (const role of signatures) {
      const base = y + 14;
      doc.fillColor(INK).font(REGULAR).fontSize(9);
      doc.text(`${role}:`, MARGIN, base - 9, { lineBreak: false });
      doc.text("Signature:", signatureAt, base - 9, { lineBreak: false });
      doc.text("Date:", dateAt, base - 9, { lineBreak: false });
      doc.lineWidth(0.6).strokeColor(MUTED);
      doc.moveTo(MARGIN + label, base + 1).lineTo(nameEnd, base + 1).stroke();
      doc.moveTo(signatureAt + widthOf("Signature:", REGULAR, 9) + 6, base + 1).lineTo(signatureEnd, base + 1).stroke();
      doc.moveTo(dateAt + widthOf("Date:", REGULAR, 9) + 6, base + 1).lineTo(end, base + 1).stroke();
      y += SIGN_ROW;
    }
  };

  const drawRow = (table, y, cells, { font = REGULAR, fill, height, header = false }) => {
    const { widths, section, size } = table;
    if (fill) doc.rect(MARGIN, y, CONTENT_WIDTH, height).fill(fill);
    let x = MARGIN;
    cells.forEach((cell, i) => {
      const text = cell ?? "";
      const column = section.columns[i];
      const right = alignsRight(column);
      doc.fillColor(!header && right && looksNegative(text) ? RED : INK).font(font).fontSize(size)
        .text(text, x + PAD_X, y + PAD_Y, { width: widths[i] - 2 * PAD_X, align: right ? "right" : "left" });
      x += widths[i];
    });
    doc.lineWidth(0.5).strokeColor(GRID).rect(MARGIN, y, CONTENT_WIDTH, height).stroke();
    let lineX = MARGIN;
    widths.slice(0, -1).forEach((w, i) => {
      lineX += w;
      // A heavier line between the Summary's two halves.
      const between = table.section.pairs && i === 1;
      doc.lineWidth(between ? 1.2 : 0.5).moveTo(lineX, y).lineTo(lineX, y + height).stroke();
    });
    return height;
  };

  const drawFragment = (table, block, top) => {
    let y = top;
    const title = block.continued ? `${table.section.title} (continued)` : table.section.title;
    doc.fillColor(block.continued ? MUTED : GREEN).font(BOLD).fontSize(TITLE_SIZE).text(title, MARGIN, y, { width: CONTENT_WIDTH, lineBreak: false });
    y += titleHeight;
    y += drawRow(table, y, table.header, { font: BOLD, fill: HEAD_FILL, height: table.head, header: true });
    if (!table.cells.length) {
      doc.fillColor(MUTED).font(ITALIC).fontSize(table.size).text(table.empty, MARGIN + PAD_X, y + PAD_Y, { width: CONTENT_WIDTH - 2 * PAD_X });
      doc.lineWidth(0.5).strokeColor(GRID).rect(MARGIN, y, CONTENT_WIDTH, table.rows[0]).stroke();
      y += table.rows[0];
    }
    for (let i = block.from; i < block.to && table.cells.length; i += 1) y += drawRow(table, y, table.cells[i], { height: table.rows[i] });
    if (block.foot) y += drawRow(table, y, table.totals, { font: BOLD, fill: TOTAL_FILL, height: table.foot });
    return y - top;
  };

  const drawFooter = (number, count) => {
    const y = BODY_BOTTOM + 9;
    doc.moveTo(MARGIN, BODY_BOTTOM + 4).lineTo(MARGIN + CONTENT_WIDTH, BODY_BOTTOM + 4).strokeColor(GRID).lineWidth(0.5).stroke();
    doc.fillColor(MUTED).font(ITALIC).fontSize(7.5).text(`${SYSTEM_NOTE} Generated ${generated}.`, MARGIN, y, { width: CONTENT_WIDTH - 80, lineBreak: false });
    doc.font(REGULAR).fontSize(7.5).text(`Page ${number} of ${count}`, MARGIN, y, { width: CONTENT_WIDTH, align: "right", lineBreak: false });
  };

  // ---- Plan the pages, then draw them.
  const measured = reports.map((report) => ({
    tables: [...(report.summary.length ? [summaryGrid(report)] : []), ...report.sections].map(measureTable),
    header: drawHeader(report, false),
    runningHeader: drawRunningHeader(report, false),
  }));
  const pages = paginate(measured.map((m) => ({
    header: m.header,
    runningHeader: m.runningHeader,
    signOff: signOffHeight,
    tables: m.tables.map((t) => ({ title: titleHeight, continuedTitle: titleHeight, head: t.head, rows: t.rows, foot: t.foot })),
  })), { page: BODY_HEIGHT, gap: TABLE_GAP });

  pages.forEach((page, index) => {
    if (index > 0) doc.addPage();
    const report = reports[page.report];
    const { tables } = measured[page.report];
    let y = MARGIN + (page.first ? drawHeader(report, true) : drawRunningHeader(report, true));
    for (const block of page.blocks) {
      if (block.type === "signoff") drawSignOff();
      else y += drawFragment(tables[block.table], block, y) + TABLE_GAP;
    }
    drawFooter(index + 1, pages.length);
  });
  doc.end();
});
